1: import { useEffect, useRef, type RefObject } from 'react';
2: 
3: const FOCAVEIS = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
4: 
5: /**
6:  * Enquanto `ativo`: leva o foco para dentro do painel, prende o Tab nele, chama `aoFechar` com Esc
7:  * e devolve o foco a quem estava focado antes de abrir.
8:  */
9: export function useFocusTrap(ativo: boolean, painel: RefObject<HTMLElement | null>, aoFechar: () => void) {
10:   const fechar = useRef(aoFechar);
11:   fechar.current = aoFechar;
12: 
13:   useEffect(() => {
14:     if (!ativo) return;
15:     const anterior = document.activeElement as HTMLElement | null;
16:     const el = painel.current;
17:     (el?.querySelector<HTMLElement>(FOCAVEIS) ?? el)?.focus();
18:     const tecla = (e: KeyboardEvent) => {
19:       if (e.key === 'Escape') {
20:         e.stopPropagation();
21:         fechar.current();
22:         return;
23:       }
24:       if (e.key !== 'Tab' || !el) return;
25:       const itens = Array.from(el.querySelectorAll<HTMLElement>(FOCAVEIS));
26:       if (itens.length === 0) {
27:         e.preventDefault();
28:         return;
29:       }
30:       const primeiro = itens[0];
31:       const ultimo = itens[itens.length - 1];
32:       if (e.shiftKey && document.activeElement === primeiro) {
33:         e.preventDefault();
34:         ultimo.focus();
35:       } else if (!e.shiftKey && document.activeElement === ultimo) {
36:         e.preventDefault();
37:         primeiro.focus();
38:       }
39:     };
40:     document.addEventListener('keydown', tecla);
41:     return () => {
42:       document.removeEventListener('keydown', tecla);
43:       anterior?.focus?.();
44:     };
45:   }, [ativo, painel]);
46: }

