export function usePreferenciasDashboard() {
  const [prefs, setPrefs] = useState<PreferenciasDashboard>(() => lerPreferenciasDashboard(window.localStorage));
  const [anuncio, setAnuncio] = useState('');

  const gravar = useCallback((nova: PreferenciasDashboard) => {
    setPrefs(nova);
    gravarPreferenciasDashboard(nova, window.localStorage);
  }, []);

  const alternar = useCallback((id: CartaoDashboardId) => {
    const titulo = cartaoPorId(id).titulo;
    const oculto = prefs.ocultos.includes(id);
    const nova = { ...prefs, ocultos: oculto ? prefs.ocultos.filter(x => x !== id) : [...prefs.ocultos, id] };
    gravar(nova);
    setAnuncio(oculto ? `Cartão ${titulo} visível.` : `Cartão ${titulo} oculto.`);
  }, [prefs, gravar]);

  const mover = useCallback((id, direcao) => {
    const novaOrdem = moverCartao(prefs.ordem, id, direcao);
    if (novaOrdem === prefs.ordem) return;
    gravar({ ...prefs, ordem: novaOrdem });
    setAnuncio(`Cartão ${cartaoPorId(id).titulo} movido para a posição ${novaOrdem.indexOf(id) + 1}.`);
  }, [prefs, gravar]);

  const restaurar = useCallback(() => {
    gravar(preferenciasDashboardPadrao());
    setAnuncio('Preferências do dashboard restauradas.');
  }, [gravar]);

  return { ...prefs, anuncio, alternar, mover, restaurar };
}
