import { useCallback, useState } from 'react';
import {
  cartaoPorId,
  gravarPreferenciasDashboard,
  lerPreferenciasDashboard,
  moverCartao,
  preferenciasDashboardPadrao,
  type CartaoDashboardId,
  type PreferenciasDashboard,
} from '../../lib/dashboard';

/** Ordem e visibilidade dos cartões do Dashboard, lembradas em `localStorage`. */
export function usePreferenciasDashboard() {
  const [prefs, setPrefs] = useState<PreferenciasDashboard>(() => lerPreferenciasDashboard(window.localStorage));
  const [anuncio, setAnuncio] = useState('');

  const gravar = useCallback((nova: PreferenciasDashboard) => {
    setPrefs(nova);
    gravarPreferenciasDashboard(nova, window.localStorage);
    return nova;
  }, []);

  const alternar = useCallback(
    (id: CartaoDashboardId) => {
      const oculto = prefs.ocultos.includes(id);
      gravar({
        ...prefs,
        ocultos: oculto ? prefs.ocultos.filter((item) => item !== id) : [...prefs.ocultos, id],
      });
      setAnuncio(`Cartão ${cartaoPorId(id).titulo} ${oculto ? 'visível' : 'oculto'}.`);
    },
    [prefs, gravar],
  );

  const mover = useCallback(
    (id: CartaoDashboardId, direcao: -1 | 1) => {
      const ordem = moverCartao(prefs.ordem, id, direcao);
      if (ordem === prefs.ordem) return;
      gravar({ ...prefs, ordem });
      setAnuncio(`Cartão ${cartaoPorId(id).titulo} movido para a posição ${ordem.indexOf(id) + 1}.`);
    },
    [prefs, gravar],
  );

  const restaurar = useCallback(() => {
    gravar(preferenciasDashboardPadrao());
    setAnuncio('Preferências do dashboard restauradas.');
  }, [gravar]);

  return { ...prefs, anuncio, alternar, mover, restaurar };
}

import { Button, IconButton, Modal } from '../../ds';
import { cartaoPorId, type CartaoDashboardId, type PreferenciasDashboard } from '../../lib/dashboard';
import './PersonalizarDashboard.css';

interface Props {
  aberto: boolean;
  prefs: PreferenciasDashboard;
  onFechar: () => void;
  onAlternar: (id: CartaoDashboardId) => void;
  onMover: (id: CartaoDashboardId, direcao: -1 | 1) => void;
  onRestaurar: () => void;
}

/** Lista todos os cartões, inclusive os ocultos, para escolher visibilidade e ordem. */
export function PersonalizarDashboard({ aberto, prefs, onFechar, onAlternar, onMover, onRestaurar }: Props) {
  return (
    <Modal
      aberto={aberto}
      titulo="Personalizar dashboard"
      onFechar={onFechar}
      tamanho="medio"
      rodape={
        <>
          <Button variante="secundario" onClick={onRestaurar}>
            Restaurar padrão
          </Button>
          <Button onClick={onFechar}>Concluir</Button>
        </>
      }
    >
      <p className="personalizar-dashboard__ajuda">
        Escolha o que aparece e em que ordem. As preferências ficam salvas neste navegador.
      </p>
      <ul className="personalizar-dashboard__lista" aria-label="Cartões do dashboard">
        {prefs.ordem.map((id, indice) => {
          const cartao = cartaoPorId(id);
          const visivel = !prefs.ocultos.includes(id);
          return (
            <li key={id} className="personalizar-dashboard__item">
              <span className="personalizar-dashboard__nome">{cartao.titulo}</span>
              {visivel ? null : <span className="personalizar-dashboard__marca">Oculto</span>}
              <div className="personalizar-dashboard__acoes">
                <Button
                  variante={visivel ? 'fantasma' : 'secundario'}
                  tamanho="pequeno"
                  aria-pressed={visivel}
                  aria-label={`${visivel ? 'Ocultar' : 'Mostrar'} ${cartao.titulo}`}
                  onClick={() => onAlternar(id)}
                >
                  {visivel ? 'Ocultar' : 'Mostrar'}
                </Button>
                <IconButton
                  aria-label={`Mover ${cartao.titulo} para cima`}
                  icone="↑"
                  tamanho="pequeno"
                  disabled={indice === 0}
                  onClick={() => onMover(id, -1)}
                />
                <IconButton
                  aria-label={`Mover ${cartao.titulo} para baixo`}
                  icone="↓"
                  tamanho="pequeno"
                  disabled={indice === prefs.ordem.length - 1}
                  onClick={() => onMover(id, 1)}
                />
              </div>
            </li>
          );
        })}
      </ul>
    </Modal>
  );
}

.personalizar-dashboard__ajuda {
  margin: 0 0 var(--esp-3);
  color: var(--cor-texto-suave);
  font-size: var(--texto-sm);
}

.personalizar-dashboard__lista {
  display: grid;
  gap: var(--esp-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.personalizar-dashboard__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--esp-2) var(--esp-3);
  padding: var(--esp-2) 0;
  border-bottom: 1px solid var(--cor-borda);
}

.personalizar-dashboard__item:last-child {
  border-bottom: 0;
}

.personalizar-dashboard__nome {
  font-size: var(--texto-sm);
  font-weight: 500;
  overflow-wrap: anywhere;
}

.personalizar-dashboard__marca {
  justify-self: start;
  color: var(--cor-texto-mudo);
  font-size: var(--texto-xs);
}

.personalizar-dashboard__acoes {
  display: flex;
  align-items: center;
  gap: var(--esp-1);
}

@media (max-width: 30rem) {
  .personalizar-dashboard__item {
    grid-template-columns: minmax(0, 1fr);
  }

  .personalizar-dashboard__acoes {
    flex-wrap: wrap;
  }
}

