import { screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import { gerarExemplo } from '../data/exemplo';
import { hojeISO } from '../domain/date';
import { CARTOES_DASHBOARD, CHAVE_DASHBOARD, lerPreferenciasDashboard, moverCartao, preferenciasDashboardPadrao } from '../lib/dashboard';
import { CHAVE_ESTADO } from '../storage/storage';
import { construirEstado, renderizarApp } from './helpers';

const HOJE = hojeISO();
const TODOS = CARTOES_DASHBOARD.map((cartao) => cartao.id);
const ORDEM_PADRAO = CARTOES_DASHBOARD.map((cartao) => cartao.titulo);

const estado = () => gerarExemplo(HOJE);

function rotulosVisiveis() {
  const grade = screen.getByRole('group', { name: 'Cartões do dashboard' });
  return Array.from(grade.querySelectorAll('.kpi__rotulo, .ds-cartao__titulo')).map((el) => el.textContent);
}

function nomesNoPainel() {
  const painel = screen.getByRole('dialog', { name: 'Personalizar dashboard' });
  const lista = within(painel).getByRole('list', { name: 'Cartões do dashboard' });
  return Array.from(lista.querySelectorAll('.personalizar-dashboard__nome')).map((el) => el.textContent);
}

describe('dashboard personalizável', () => {
  it('critérios 1, 2, 6 e 12: abre o painel, lista todos os cartões na ordem padrão e prende o foco', async () => {
    const usuario = userEvent.setup();
    renderizarApp('/', estado());

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    const painel = screen.getByRole('dialog', { name: 'Personalizar dashboard' });
    expect(within(painel).getByRole('button', { name: 'Fechar' })).toHaveFocus();
    expect(rotulosVisiveis()).toEqual(ORDEM_PADRAO);
    expect(nomesNoPainel()).toEqual(ORDEM_PADRAO);
    expect(within(painel).getByRole('button', { name: 'Mover Saldo total atual para cima' })).toBeDisabled();
    expect(within(painel).getByRole('button', { name: 'Mover Recorrências usadas na projeção para baixo' })).toBeDisabled();

    await usuario.keyboard('{Escape}');
    expect(screen.queryByRole('dialog', { name: 'Personalizar dashboard' })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Personalizar dashboard' })).toHaveFocus();
  });

  it('critérios 3, 5 e 13: oculta e mostra um cartão, anuncia e persiste após recarregar', async () => {
    const usuario = userEvent.setup();
    const primeira = renderizarApp('/', estado());

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    await usuario.click(screen.getByRole('button', { name: 'Ocultar Despesas por categoria' }));
    expect(within(screen.getByRole('group', { name: 'Cartões do dashboard' })).queryByText('Despesas por categoria')).not.toBeInTheDocument();
    expect(document.querySelector('.dashboard .sr-somente')?.textContent).toBe('Cartão Despesas por categoria oculto.');
    expect(JSON.parse(localStorage.getItem(CHAVE_DASHBOARD) ?? '{}').ocultos).toContain('despesas-categoria');

    primeira.unmount();
    renderizarApp('/', estado());
    expect(rotulosVisiveis()).not.toContain('Despesas por categoria');

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    await usuario.click(screen.getByRole('button', { name: 'Mostrar Despesas por categoria' }));
    expect(rotulosVisiveis()).toContain('Despesas por categoria');
    expect(document.querySelector('.dashboard .sr-somente')?.textContent).toBe('Cartão Despesas por categoria visível.');
  });

  it('critérios 2, 4 e 13: move um cartão, mantém o foco e persiste a nova ordem', async () => {
    const usuario = userEvent.setup();
    const primeira = renderizarApp('/', estado());

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    const mover = screen.getByRole('button', { name: 'Mover Projeção do saldo para cima' });
    mover.focus();
    await usuario.click(mover);
    expect(document.activeElement).toBe(mover);
    expect(document.querySelector('.dashboard .sr-somente')?.textContent).toBe('Cartão Projeção do saldo movido para a posição 9.');
    expect(rotulosVisiveis().slice(7, 10)).toEqual(['Orçamento do mês', 'Projeção do saldo', 'Metas ativas']);

    primeira.unmount();
    renderizarApp('/', estado());
    expect(rotulosVisiveis().slice(7, 10)).toEqual(['Orçamento do mês', 'Projeção do saldo', 'Metas ativas']);
    expect(JSON.parse(localStorage.getItem(CHAVE_DASHBOARD) ?? '{}').ordem.slice(7, 10)).toEqual(['orcamento', 'projecao', 'metas']);
  });

  it('critério 7: Restaurar padrão volta todos os cartões à ordem original e persiste', async () => {
    const usuario = userEvent.setup();
    localStorage.setItem(CHAVE_DASHBOARD, JSON.stringify({ ordem: [...TODOS].reverse(), ocultos: ['saldo', 'metas'] }));
    renderizarApp('/', estado());
    expect(rotulosVisiveis()).not.toContain('Saldo total atual');

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    await usuario.click(screen.getByRole('button', { name: 'Restaurar padrão' }));
    expect(nomesNoPainel()).toEqual(ORDEM_PADRAO);
    expect(rotulosVisiveis()).toEqual(ORDEM_PADRAO);
    expect(lerPreferenciasDashboard(localStorage)).toEqual(preferenciasDashboardPadrao());
  });

  it('critério 8: preferência malformada ou incompleta não quebra e completa a ordem', () => {
    localStorage.setItem(CHAVE_DASHBOARD, '{quebrado');
    expect(lerPreferenciasDashboard(localStorage)).toEqual(preferenciasDashboardPadrao());

    localStorage.setItem(CHAVE_DASHBOARD, JSON.stringify({ ordem: ['metas', 'desconhecido', 'metas'], ocultos: ['metas', 'x', 'metas'] }));
    const lida = lerPreferenciasDashboard(localStorage);
    expect(lida.ordem[0]).toBe('metas');
    expect(lida.ordem).toHaveLength(CARTOES_DASHBOARD.length);
    expect(new Set(lida.ordem).size).toBe(CARTOES_DASHBOARD.length);
    expect(lida.ordem.filter((id) => id !== 'metas')).toEqual(TODOS.filter((id) => id !== 'metas'));
    expect(lida.ocultos).toEqual(['metas']);

    expect(moverCartao(TODOS, 'saldo', -1)).toEqual(TODOS);
    expect(moverCartao(TODOS, 'recorrencias', 1)).toEqual(TODOS);
  });

  it('critérios 8, 9 e 10: dados e mês não mudam, e o estado inicial segue fixo', async () => {
    const usuario = userEvent.setup();
    const dados = estado();
    const { unmount } = renderizarApp('/?mes=2026-09', dados);
    const estadoAntes = localStorage.getItem(CHAVE_ESTADO);
    const saldoAntes = screen.getByTestId('saldo-total').textContent;

    await usuario.click(screen.getByRole('button', { name: 'Personalizar dashboard' }));
    await usuario.click(screen.getByRole('button', { name: 'Ocultar Receitas e despesas (6 meses)' }));
    expect(screen.getByTestId('saldo-total').textContent).toBe(saldoAntes);
    expect(screen.getByRole('group', { name: 'Mês' })).toHaveTextContent('Setembro de 2026');
    expect(localStorage.getItem(CHAVE_ESTADO)).toBe(estadoAntes);
    unmount();

    renderizarApp('/', construirEstado());
    expect(screen.getByRole('heading', { name: 'Bem-vindo! Comece criando uma conta' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Personalizar dashboard' })).toBeInTheDocument();
    expect(screen.getByRole('group', { name: 'Mês' })).toBeInTheDocument();
  });

  it('critérios 7, 11 e 14: com todos ocultos mostra a mensagem e permite restaurar', async () => {
    const usuario = userEvent.setup();
    localStorage.setItem(CHAVE_DASHBOARD, JSON.stringify({ ordem: TODOS, ocultos: TODOS }));
    renderizarApp('/', estado());

    expect(screen.getByText(/Todos os cartões estão ocultos/)).toBeInTheDocument();
    expect(screen.queryByRole('group', { name: 'Cartões do dashboard' })).not.toBeInTheDocument();
    expect(screen.getByRole('group', { name: 'Mês' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Personalizar dashboard' })).toBeInTheDocument();

    await usuario.click(screen.getByRole('button', { name: 'Restaurar padrão' }));
    expect(rotulosVisiveis()).toEqual(ORDEM_PADRAO);
    expect(lerPreferenciasDashboard(localStorage)).toEqual(preferenciasDashboardPadrao());
  });
});

