  moverCartao,
  moverCartaoPara,
  preferenciasDashboardPadrao,
  type CartaoDashboardId,
  type PreferenciasDashboard,
} from '../../lib/dashboard';

function posicaoVisivel(ordem: CartaoDashboardId[], ocultos: CartaoDashboardId[], id: CartaoDashboardId): number {
  return ordem.filter((item) => !ocultos.includes(item)).indexOf(id) + 1;
}

/** Ordem e visibilidade dos cartões do Dashboard, lembradas em `localStorage`. */
export function usePreferenciasDashboard() {
  const [prefs, setPrefs] = useState<PreferenciasDashboard>(() => lerPreferenciasDashboard(window.localStorage));
  const [anuncio, setAnuncio] = useState('');

  const gravar = useCallback((nova: PreferenciasDashboard) => {
    setPrefs(nova);
    gravarPreferenciasDashboard(nova, window.localStorage);
    return nova;
  }, []);

  const alternar = useCallback(
    (id: CartaoDashboardId) => {
      const oculto = prefs.ocultos.includes(id);
      gravar({
        ...prefs,
        ocultos: oculto ? prefs.ocultos.filter((item) => item !== id) : [...prefs.ocultos, id],
      });
      setAnuncio(`Cartão ${cartaoPorId(id).titulo} ${oculto ? 'visível' : 'oculto'}.`);
    },
    [prefs, gravar],
  );

  const mover = useCallback(
    (id: CartaoDashboardId, direcao: -1 | 1) => {
      const ordem = moverCartao(prefs.ordem, id, direcao);
      if (ordem === prefs.ordem) return;
      gravar({ ...prefs, ordem });
      setAnuncio(`Cartão ${cartaoPorId(id).titulo} movido para a posição ${posicaoVisivel(ordem, prefs.ocultos, id)}.`);
    },
    [prefs, gravar],
  );

  const moverPara = useCallback(
    (id: CartaoDashboardId, destino: CartaoDashboardId) => {
      const ordem = moverCartaoPara(prefs.ordem, id, destino);
      if (ordem === prefs.ordem) return;
      gravar({ ...prefs, ordem });
      setAnuncio(`Cartão ${cartaoPorId(id).titulo} movido para a posição ${posicaoVisivel(ordem, prefs.ocultos, id)}.`);
    },
    [prefs, gravar],
  );

  const restaurar = useCallback(() => {
    gravar(preferenciasDashboardPadrao());
    setAnuncio('Preferências do dashboard restauradas.');
  }, [gravar]);

  return { ...prefs, anuncio, alternar, mover, moverPara, restaurar };
}

import { useId } from 'react';
import { Button, IconButton } from '../../ds';
import { cartaoPorId, type CartaoDashboardId } from '../../lib/dashboard';
import './EdicaoDashboard.css';

interface BarraProps {
  onRestaurar: () => void;
  onConcluir: () => void;
}

/** Barra do modo de personalização, exibida acima da grade do Dashboard. */
export function BarraEdicao({ onRestaurar, onConcluir }: BarraProps) {
  return (
    <div className="edicao-dashboard__barra" role="region" aria-label="Modo de personalização">
      <p className="edicao-dashboard__dica">
        Arraste os cartões para reordenar. Use as setas para mover sem mouse e o ✕ para ocultar.
      </p>
      <div className="edicao-dashboard__acoes">
        <Button variante="secundario" tamanho="pequeno" onClick={onRestaurar}>
          Restaurar padrão
        </Button>
        <Button tamanho="pequeno" onClick={onConcluir}>
          Concluir
        </Button>
      </div>
    </div>
  );
}

interface ControlesProps {
  id: CartaoDashboardId;
  primeiro: boolean;
  ultimo: boolean;
  onMover: (id: CartaoDashboardId, direcao: -1 | 1) => void;
  onOcultar: (id: CartaoDashboardId) => void;
}

/** Controles de um cartão no modo de edição: arrastar, mover e ocultar. */
export function ControlesCartao({ id, primeiro, ultimo, onMover, onOcultar }: ControlesProps) {
  const titulo = cartaoPorId(id).titulo;
  return (
    <div className="edicao-dashboard__controles">
      <span className="edicao-dashboard__arrastar" title="Arraste para reordenar" aria-hidden="true">
        ⠿
      </span>
      <span className="edicao-dashboard__nome">{titulo}</span>
      <div className="edicao-dashboard__acoes">
        <IconButton aria-label={`Mover ${titulo} para cima`} icone="↑" tamanho="pequeno" disabled={primeiro} onClick={() => onMover(id, -1)} />
        <IconButton aria-label={`Mover ${titulo} para baixo`} icone="↓" tamanho="pequeno" disabled={ultimo} onClick={() => onMover(id, 1)} />
        <IconButton aria-label={`Ocultar ${titulo}`} icone="✕" tamanho="pequeno" onClick={() => onOcultar(id)} />
      </div>
    </div>
  );
}

interface OcultosProps {
  ids: CartaoDashboardId[];
  onMostrar: (id: CartaoDashboardId) => void;
}

/** Cartões ocultos no modo de edição, com a ação de mostrá-los de novo. */
export function CartoesOcultos({ ids, onMostrar }: OcultosProps) {
  const idTitulo = useId();
  return (
    <section className="edicao-dashboard__ocultos" aria-labelledby={idTitulo}>
      <h2 id={idTitulo} className="edicao-dashboard__ocultos-titulo">
        Cartões ocultos
      </h2>
      <ul className="edicao-dashboard__ocultos-lista">
        {ids.map((id) => {
          const titulo = cartaoPorId(id).titulo;
          return (
            <li key={id} className="edicao-dashboard__ocultos-item">
              <span>{titulo}</span>
              <Button variante="secundario" tamanho="pequeno" aria-label={`Mostrar ${titulo}`} onClick={() => onMostrar(id)}>
                Mostrar
              </Button>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

.edicao-dashboard__barra {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--esp-3);
  padding: var(--esp-3) var(--esp-4);
  border: 1px dashed var(--cor-borda-forte);
  border-radius: var(--raio);
  background: var(--cor-superficie-alt);
}

.edicao-dashboard__dica {
  flex: 1 1 16rem;
  margin: 0;
  color: var(--cor-texto-suave);
  font-size: var(--texto-sm);
}

.edicao-dashboard__acoes {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-1);
}

.edicao-dashboard__controles {
  display: flex;
  align-items: center;
  gap: var(--esp-2);
  padding: var(--esp-1) var(--esp-2);
  border: 1px dashed var(--cor-borda-forte);
  border-radius: var(--raio-pequeno);
  background: var(--cor-superficie-alt);
}

.edicao-dashboard__arrastar {
  color: var(--cor-texto-mudo);
  cursor: grab;
  font-size: var(--texto-lg);
  line-height: 1;
}

.edicao-dashboard__nome {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--cor-texto-suave);
  font-size: var(--texto-xs);
  font-weight: 600;
  overflow-wrap: anywhere;
}

.edicao-dashboard__ocultos {
  display: grid;
  gap: var(--esp-2);
  padding: var(--esp-4);
  border: 1px dashed var(--cor-borda-forte);
  border-radius: var(--raio);
}

.edicao-dashboard__ocultos-titulo {
  margin: 0;
  font-size: var(--texto-lg);
  font-weight: var(--peso-semibold);
}

.edicao-dashboard__ocultos-lista {
  display: grid;
  gap: var(--esp-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.edicao-dashboard__ocultos-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--esp-3);
  font-size: var(--texto-sm);
}

@media (max-width: 40rem) {
  .edicao-dashboard__controles {
    flex-wrap: wrap;
  }
}

